package cn.xingbao.controller;
import cn.xingbao.common.ApiResponse; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.IOException; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/api/v1/files") public class FileController { @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ApiResponse<Map<String,String>> upload(@RequestParam MultipartFile file) throws IOException {if(file.isEmpty()||file.getSize()>10*1024*1024)throw new IllegalArgumentException("文件不能为空且不得超过10MB");String ext=Optional.ofNullable(file.getOriginalFilename()).filter(n->n.contains(".")).map(n->n.substring(n.lastIndexOf('.'))).orElse("");if(!Set.of(".jpg",".jpeg",".png",".pdf").contains(ext.toLowerCase()))throw new IllegalArgumentException("仅支持 JPG、PNG、PDF");Files.createDirectories(Path.of("uploads"));String name=UUID.randomUUID()+ext;Files.copy(file.getInputStream(),Path.of("uploads",name),StandardCopyOption.REPLACE_EXISTING);return ApiResponse.ok(Map.of("url","/uploads/"+name));}}
